c=read(B/'checkpoint.json');c.update(website_published=True,checkpoint_at=datetime.now(timezone.utc).isoformat(),public_live_version=p['public_live_version'],dataset_version=p['dataset_version'],publication_evidence=str(B/'publication-checkpoint.json'),current_work_items=[{'label':k.capitalize(),'status':v['status'],'scope':v['note']}for k,v in ms.items()],next_action='Supplied-main contribution published and closed. Existing heartbeat continues oldest eligible arrival; new or changed evidence reopens this source.');write(B/'checkpoint.json',c)
